:root{--bg:#090b0f;--panel:#12161d;--panel2:#191f28;--line:#2b3440;--txt:#f5f7fa;--muted:#9aa6b2;--gold:#d8b56b;--green:#77c692;--blue:#6ea8e8;--red:#df7a7a;--max:1050px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--txt);font-family:Inter,system-ui,Arial,sans-serif;line-height:1.55}button,input,select,textarea{font:inherit}.wrap{width:min(var(--max),calc(100% - 28px));margin:auto}.top{position:sticky;top:0;background:#090b0ff2;border-bottom:1px solid var(--line);z-index:20}.topin{min-height:62px;display:flex;align-items:center;justify-content:space-between}.brand{font-weight:900;letter-spacing:.12em}.brand span{color:var(--gold)}.top a{color:var(--gold);text-decoration:none}.hero{padding:42px 0 18px}.hero h1{font-size:clamp(34px,6vw,62px);line-height:1;margin:6px 0 12px}.hero p{color:#c5ccd5;max-width:760px}.eyebrow{font-size:12px;color:var(--gold);font-weight:900;letter-spacing:.12em;text-transform:uppercase}.current{margin:18px 0 24px;background:linear-gradient(135deg,#1b1b15,#12161d);border:1px solid #6a5937;border-radius:16px;padding:20px}.current h2{margin:4px 0 8px;font-size:26px}.current p{margin:6px 0;color:#ccd2da}.current .big{font-size:14px;color:var(--gold);font-weight:900;text-transform:uppercase}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0}.stat{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px}.stat span{display:block;color:var(--muted);font-size:12px}.stat strong{font-size:25px}.toolbar{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0 24px}.btn{border:1px solid var(--line);background:#171c24;color:var(--txt);border-radius:9px;padding:10px 13px;font-weight:800;cursor:pointer}.btn.primary{background:var(--gold);color:#17120b;border-color:var(--gold)}.loadbox{padding:18px;border:1px dashed var(--line);border-radius:12px;color:var(--muted);margin:12px 0}.errorbox{padding:16px;border:1px solid #713d3d;background:#241315;border-radius:12px;color:#f3caca;display:none;margin:12px 0}.phase{background:var(--panel);border:1px solid var(--line);border-radius:14px;margin:10px 0;overflow:hidden}.phase>summary{cursor:pointer;list-style:none;padding:16px}.phase>summary::-webkit-details-marker{display:none}.phase-title{display:flex;gap:12px;align-items:center}.num{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:var(--gold);color:#111;font-weight:900}.phase-title small{display:block;color:var(--muted)}.tasks{padding:0 12px 12px}.task{background:#0d1117;border:1px solid var(--line);border-radius:11px;margin:9px 0;overflow:hidden}.task>summary{cursor:pointer;list-style:none;padding:14px}.task>summary::-webkit-details-marker{display:none}.task-head{display:flex;gap:10px;align-items:center}.dot{width:10px;height:10px;border-radius:50%;background:#606b78}.task[data-status="done"] .dot{background:var(--green)}.task[data-status="doing"] .dot{background:var(--blue)}.task[data-status="blocked"] .dot{background:var(--red)}.task-head span{margin-left:auto;color:var(--muted);font-size:12px}.body{border-top:1px solid var(--line);padding:15px}.body p{color:#c7ced7}.question{background:var(--panel2);border-left:3px solid var(--gold);padding:12px;margin:12px 0}.field{margin:12px 0}.field label{display:block;font-size:13px;font-weight:800;margin-bottom:5px}.field textarea,.field select,.field input{width:100%;background:#090c10;color:var(--txt);border:1px solid var(--line);border-radius:8px;padding:10px}.field textarea{min-height:115px;resize:vertical}.row{display:grid;grid-template-columns:180px 1fr;gap:12px}.save{display:flex;justify-content:flex-end;gap:10px;align-items:center}.saved{font-size:12px;color:var(--muted)}.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:16px;margin:20px 0}.panel textarea{width:100%;min-height:130px;background:#090c10;color:var(--txt);border:1px solid var(--line);border-radius:8px;padding:10px}.decision-form{display:grid;grid-template-columns:1fr 170px auto;gap:8px}.decision-form input,.decision-form select{background:#090c10;color:var(--txt);border:1px solid var(--line);border-radius:8px;padding:10px}.decision{padding:10px 0;border-top:1px solid var(--line)}.login-shell{min-height:100vh;display:grid;place-items:center}.login{width:min(420px,calc(100% - 28px));background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:22px}.login input{width:100%;padding:11px;background:#090c10;color:var(--txt);border:1px solid var(--line);border-radius:8px;margin:5px 0 10px}.footer{padding:34px 0;color:var(--muted);font-size:12px}.toast{position:fixed;right:16px;bottom:16px;background:#171c24;border:1px solid var(--line);padding:11px 14px;border-radius:9px;display:none}@media(max-width:720px){.stats{grid-template-columns:1fr 1fr}.row,.decision-form{grid-template-columns:1fr}}
</style>
</head>
