<header class="top"><div class="wrap topin"><div class="brand">CNJP <span>ROADMAP</span></div><a href="../plan/logout.php">Sair</a></div></header>
<main class="wrap">
<section class="hero"><div class="eyebrow">Roteiro de reestruturação</div><h1>Uma tarefa por vez.</h1><p>Aqui fica registrado o que já sabemos, o que falta descobrir e o próximo passo. Não precisa entender a empresa inteira hoje. Só precisa terminar o passo atual.</p></section>
<section class="current" id="currentBox"><div class="big">O que fazer agora</div><h2 id="currentTitle">Carregando...</h2><p id="currentDesc">Buscando o próximo passo.</p><button class="btn primary" id="goCurrent">Abrir esta tarefa</button></section>
<div class="errorbox" id="errorBox"></div>
<div class="stats"><div class="stat"><span>Progresso</span><strong id="progress">0%</strong></div><div class="stat"><span>Concluídas</span><strong id="done">0</strong></div><div class="stat"><span>Em andamento</span><strong id="doing">0</strong></div><div class="stat"><span>Bloqueadas</span><strong id="blocked">0</strong></div></div>
<div class="toolbar"><button class="btn primary" id="copySummary">Copiar resumo para o ChatGPT</button><button class="btn" id="openAll">Abrir tudo</button><button class="btn" id="closeAll">Fechar tudo</button></div>
<section><div class="eyebrow">Passo a passo</div><h2>Roadmap</h2><div id="phases" class="loadbox">Carregando tarefas...</div></section>
<section class="panel"><h2>Decisões e pendências</h2><form id="decisionForm" class="decision-form"><input id="decisionTitle" placeholder="Ex.: CNJP Tech será uma marca separada"><select id="decisionStatus"><option value="open">Em aberto</option><option value="decided">Decidido</option><option value="discarded">Descartado</option></select><button class="btn primary">Registrar</button></form><div id="decisionList"></div></section>
<section class="panel"><h2>Estacionamento de ideias</h2><p>Ideias boas que não são prioridade agora.</p><textarea id="parking"></textarea><div class="save"><button class="btn" id="saveParking">Salvar ideias</button></div></section>
</main>
<footer class="footer"><div class="wrap">CNJP Roadmap • dados salvos no MySQL do Plan</div></footer><div class="toast" id="toast"></div>
<script>
let BOOT={tasks:[],notes:{},decisions:[],csrf:<?=json_encode($csrf)?>};
const phases={1:['Inventário','Descobrir o que já existe.'],2:['Possibilidades','Levantar oportunidades e limites.'],3:['Produtos','Escolher o que realmente será vendido.'],4:['Operação','Definir como entregar.'],5:['Sistemas','Organizar CRM, automações e métricas.'],6:['Marca e site','Explicar a empresa com clareza.'],7:['Aquisição','Buscar clientes de forma controlada.']};
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function toast(t){const e=document.getElementById('toast');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',2200)}
async function api(action,method='GET',body=null){const o={method,headers:{'X-CSRF-Token':BOOT.csrf}};if(body){o.headers['Content-Type']='application/json';o.body=JSON.stringify(body)}const r=await fetch('api.php?action='+action,o);let j;try{j=await r.json()}catch{throw new Error('A API respondeu em formato inválido.')}if(!r.ok||!j.ok)throw new Error(j.detail||j.message||'Erro ao carregar');if(j.csrf)BOOT.csrf=j.csrf;return j}
function currentTask(){return BOOT.tasks.find(t=>t.status!=='done')||BOOT.tasks[BOOT.tasks.length-1]}
function render(){const holder=document.getElementById('phases');holder.className='';holder.innerHTML='';for(let p=1;p<=7;p++){const ts=BOOT.tasks.filter(t=>Number(t.phase)===p),done=ts.filter(t=>t.status==='done').length;const d=document.createElement('details');d.className='phase';d.dataset.phase=p;const ct=currentTask();if(ct&&Number(ct.phase)===p)d.open=true;d.innerHTML=`<summary><div class="phase-title"><span class="num">${p}</span><div><strong>FASE ${p} — ${phases[p][0]}</strong><small>${phases[p][1]} ${done}/${ts.length} concluídas</small></div></div></summary><div class="tasks">${ts.map(taskHtml).join('')}</div>`;holder.appendChild(d)}bind();renderStats();renderCurrent();renderDecisions();document.getElementById('parking').value=BOOT.notes?.parking||''}
function taskHtml(t){const label={todo:'A fazer',doing:'Em andamento',done:'Concluída',blocked:'Bloqueada'}[t.status];return `<details class="task" id="task-${esc(t.task_key)}" data-key="${esc(t.task_key)}" data-status="${esc(t.status)}"><summary><div class="task-head"><i class="dot"></i><b>${esc(t.title)}</b><span>${label}</span></div></summary><div class="body"><p>${esc(t.explanation)}</p><div class="question"><b>O que fazer:</b><br>${esc(t.question)}</div><div class="row"><div class="field"><label>Status</label><select class="status"><option value="todo" ${t.status==='todo'?'selected':''}>A fazer</option><option value="doing" ${t.status==='doing'?'selected':''}>Em andamento</option><option value="done" ${t.status==='done'?'selected':''}>Concluída</option><option value="blocked" ${t.status==='blocked'?'selected':''}>Bloqueada</option></select></div><div class="field"><label>Resposta / o que já sabemos</label><textarea class="answer">${esc(t.answer||'')}</textarea></div></div><div class="field"><label>Observações e próximos passos</label><textarea class="notes">${esc(t.notes||'')}</textarea></div><div class="save"><span class="saved">${t.updated_at?'Salvo em '+esc(t.updated_at):''}</span><button class="btn primary saveTask">Salvar tarefa</button></div></div></details>`}
function bind(){document.querySelectorAll('.saveTask').forEach(b=>b.onclick=async()=>{const e=b.closest('.task');b.disabled=true;try{await api('save_task','POST',{task_key:e.dataset.key,status:e.querySelector('.status').value,answer:e.querySelector('.answer').value,notes:e.querySelector('.notes').value});toast('Tarefa salva');await load()}catch(x){toast(x.message)}finally{b.disabled=false}})}
function renderStats(){const total=BOOT.tasks.length,done=BOOT.tasks.filter(t=>t.status==='done').length;document.getElementById('progress').textContent=(total?Math.round(done/total*100):0)+'%';document.getElementById('done').textContent=done;document.getElementById('doing').textContent=BOOT.tasks.filter(t=>t.status==='doing').length;document.getElementById('blocked').textContent=BOOT.tasks.filter(t=>t.status==='blocked').length}
function renderCurrent(){const t=currentTask();if(!t){document.getElementById('currentTitle').textContent='Roadmap concluído';document.getElementById('currentDesc').textContent='Todas as tarefas foram concluídas.';return}document.getElementById('currentTitle').textContent=t.title;document.getElementById('currentDesc').textContent=t.question;document.getElementById('goCurrent').onclick=()=>{const el=document.getElementById('task-'+t.task_key);el.closest('.phase').open=true;el.open=true;el.scrollIntoView({behavior:'smooth',block:'center'})}}
function renderDecisions(){const h=document.getElementById('decisionList');h.innerHTML=BOOT.decisions.length?BOOT.decisions.map(d=>`<div class="decision"><b>${esc(d.title)}</b> — ${d.decision_status==='open'?'Em aberto':d.decision_status==='decided'?'Decidido':'Descartado'}</div>`).join(''):'<p>Nenhuma decisão registrada.</p>'}
async function load(){try{const j=await api('bootstrap');BOOT=j;render()}catch(e){const box=document.getElementById('errorBox');box.style.display='block';box.innerHTML='<b>Não consegui carregar as tarefas.</b><br>'+esc(e.message)+'<br><br>Atualize a página depois da correção.';document.getElementById('phases').textContent='Falha ao carregar o roadmap.';document.getElementById('currentTitle').textContent='Erro ao carregar';document.getElementById('currentDesc').textContent=e.message}}
document.getElementById('decisionForm').onsubmit=async e=>{e.preventDefault();const title=document.getElementById('decisionTitle').value.trim();if(!title)return;await api('save_decision','POST',{title,decision_status:document.getElementById('decisionStatus').value});document.getElementById('decisionTitle').value='';await load();toast('Decisão registrada')};
document.getElementById('saveParking').onclick=async()=>{await api('save_project_note','POST',{note_key:'parking',content:document.getElementById('parking').value});toast('Ideias salvas')};
document.getElementById('openAll').onclick=()=>document.querySelectorAll('details').forEach(d=>d.open=true);document.getElementById('closeAll').onclick=()=>document.querySelectorAll('details').forEach(d=>d.open=false);
document.getElementById('copySummary').onclick=async()=>{const l=['CNJP — ESTADO ATUAL',''];BOOT.tasks.forEach(t=>{l.push(`[${t.status}] Fase ${t.phase} — ${t.title}`);if((t.answer||'').trim())l.push('Resposta: '+t.answer.trim());if((t.notes||'').trim())l.push('Observações: '+t.notes.trim());l.push('')});if(BOOT.decisions.length){l.push('DECISÕES');BOOT.decisions.forEach(d=>l.push(`[${d.decision_status}] ${d.title}`))}if((BOOT.notes?.parking||'').trim())l.push('','IDEIAS ESTACIONADAS',BOOT.notes.parking);await navigator.clipboard.writeText(l.join('\n'));toast('Resumo copiado')};
load();
</script>
<?php endif; ?>
</body></html>